package webhook

import (
    "crypto/hmac"
    "crypto/sha256"
    "encoding/hex"
    "fmt"
    "strconv"
    "time"
)

func Verify(secret []byte, timestamp string, body []byte, signature string, now time.Time) error {
    sec, err := strconv.ParseInt(timestamp, 10, 64)
    if err != nil { return fmt.Errorf("invalid webhook timestamp") }
    delta := now.Sub(time.Unix(sec, 0))
    if delta < -5*time.Minute || delta > 5*time.Minute { return fmt.Errorf("webhook timestamp outside window") }
    provided, err := hex.DecodeString(signature)
    if err != nil { return fmt.Errorf("invalid webhook signature encoding") }
    mac := hmac.New(sha256.New, secret)
    _, _ = mac.Write([]byte(timestamp + "."))
    _, _ = mac.Write(body)
    if !hmac.Equal(mac.Sum(nil), provided) { return fmt.Errorf("invalid webhook signature") }
    return nil
}

